main_section_html:
{% set order_conf_name = frappe.form_dict.get("name") %}
{% set oc = frappe.get_doc("Order Confirmation", order_conf_name) if order_conf_name else None %}
{% set doc = frappe.get_doc("Sales Order", oc.sales_order) if oc and oc.sales_order else None %}
{% set contact_email = (oc.contact_email or (doc.contact_email if doc else "")) %}
{% set contact_phone = (oc.contact_mobile or oc.contact_phone or (doc.contact_phone if doc else "")) %}
{% set masked_phone = ('*' * (contact_phone|length - 4)) + contact_phone[-4:] if contact_phone else '' %}
{% set currency = doc.currency or oc.currency or "INR" %}
{% set currency_symbols = {
    "INR": "₹",
    "USD": "$",
    "EUR": "€",
    "GBP": "£",
    "AED": "د.إ",
    "SAR": "﷼"
} %}
{% set currency_symbol = currency_symbols.get(currency, currency + " ") %}
{% if not oc %}
    <div style="padding:20px; color:red; font-weight:bold;">
        Invalid or missing Order Confirmation.
    </div>
{% else %}

<style>
* {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary: #1e40af;
    --primary-light: #3b82f6;
    --primary-dark: #1e3a8a;
    --success: #059669;
    --warning: #d97706;
    --danger: #dc2626;
    --info: #0891b2;
    --bg-primary: #f8fafc;
    --bg-secondary: #ffffff;
    --bg-tertiary: #f1f5f9;
    --text-primary: #0f172a;
    --text-secondary: #475569;
    --text-tertiary: #64748b;
    --border-color: #e2e8f0;
    --border-color-dark: #cbd5e1;
    --accent-green: #22c55e;
    --accent-gold: #f59e0b;
    --radius-sm: 8px;
    --radius-md: 12px;
    --radius-lg: 16px;
    --shadow-sm: 0 1px 2px 0 rgba(0, 0, 0, 0.05);
    --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.1);
    --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.1);
    --transition: all 0.3s cubic-bezier(0.4, 0, 0.2, 1);
}

body {
    font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, 'Helvetica Neue', sans-serif;
    background: linear-gradient(135deg, var(--bg-primary) 0%, var(--bg-tertiary) 100%);
    min-height: 100vh;
    padding: 24px 16px;
    color: var(--text-primary);
    overflow-x: hidden;
}

.container {
    max-width: 1000px;
    width: 100%;
    margin: 0 auto;
}

/* ===== HEADER ===== */
.header {
    text-align: center;
    margin-bottom: 32px;
}

.header-badge {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    background: linear-gradient(135deg, rgba(34, 197, 94, 0.15), rgba(34, 197, 94, 0.05));
    color: var(--accent-green);
    padding: 10px 20px;
    border-radius: 50px;
    font-size: 0.85rem;
    font-weight: 700;
    margin-bottom: 12px;
    border: 2px solid var(--accent-green);
    letter-spacing: 0.5px;
    max-width: 100%;
}

.header-badge::before {
    content: "✓";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 22px;
    height: 22px;
    background: var(--accent-green);
    color: white;
    border-radius: 50%;
    font-weight: bold;
    font-size: 13px;
    flex-shrink: 0;
}

.header h1 {
    font-size: 2.2rem;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 8px;
    letter-spacing: -0.5px;
    word-break: break-word;
}

.header-subtitle {
    font-size: 1.05rem;
    color: var(--text-secondary);
    font-weight: 500;
    line-height: 1.6;
    word-break: break-word;
}

/* ===== RISK / VERIFICATION BANNER ===== */
.risk-banner {
    background: linear-gradient(135deg, rgba(245, 158, 11, 0.1) 0%, rgba(245, 158, 11, 0.05) 100%);
    border: 2px solid var(--accent-gold);
    border-radius: var(--radius-lg);
    padding: 18px 22px;
    margin-bottom: 24px;
    display: flex;
    gap: 14px;
    align-items: flex-start;
    box-shadow: 0 4px 12px rgba(120, 53, 15, 0.08);
    min-width: 0;
}

.risk-banner-icon {
    font-size: 24px;
    flex-shrink: 0;
}

.risk-banner-content {
    flex: 1;
    min-width: 0;
}

.risk-banner-title {
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 6px;
    font-size: 0.98rem;
    text-transform: uppercase;
    letter-spacing: 0.5px;
}

.risk-banner-text {
    font-size: 0.88rem;
    color: var(--text-secondary);
    line-height: 1.6;
    font-weight: 500;
    word-break: break-word;
}

.risk-score {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    background: white;
    padding: 6px 12px;
    border-radius: 8px;
    font-size: 0.82rem;
    font-weight: 700;
    margin-top: 10px;
    box-shadow: 0 2px 4px rgba(120, 53, 15, 0.1);
    text-transform: uppercase;
    letter-spacing: 0.3px;
    max-width: 100%;
    flex-wrap: wrap;
}

.risk-score.verified {
    color: var(--accent-green);
    border: 2px solid var(--accent-green);
}

.risk-score.unverified {
    color: var(--warning);
    border: 2px solid var(--warning);
}

/* ===== GRID & CARDS ===== */
.main-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
    margin-bottom: 24px;
}

.card {
    background: var(--bg-secondary);
    border: 1px solid var(--border-color);
    border-radius: var(--radius-lg);
    padding: 24px;
    box-shadow: var(--shadow-sm);
    transition: var(--transition);
    min-width: 0;
}

.card:hover {
    box-shadow: var(--shadow-md);
    border-color: var(--border-color-dark);
}

.card.full-width {
    grid-column: 1 / -1;
}

.card-header {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 20px;
    padding-bottom: 16px;
    border-bottom: 2px solid var(--border-color);
    min-width: 0;
}

.card-header-icon {
    width: 40px;
    height: 40px;
    background: linear-gradient(135deg, var(--accent-gold), var(--primary-light));
    border-radius: var(--radius-md);
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 22px;
    flex-shrink: 0;
    box-shadow: 0 4px 12px rgba(245, 158, 11, 0.2);
}

.card-header h2 {
    font-size: 1.1rem;
    font-weight: 600;
    color: var(--text-primary);
    margin: 0;
    min-width: 0;
    word-break: break-word;
}

/* ===== ORDER SUMMARY ===== */
.order-summary-grid {
    display: grid;
    grid-template-columns: repeat(2, 1fr);
    gap: 12px;
    margin-bottom: 24px;
}

.summary-card {
    background: var(--bg-primary);
    padding: 14px;
    border-radius: var(--radius-md);
    border: 1px solid var(--border-color);
    text-align: center;
    min-width: 0;
}

.summary-label {
    font-size: 0.75rem;
    text-transform: uppercase;
    font-weight: 600;
    color: var(--text-tertiary);
    letter-spacing: 0.5px;
    margin-bottom: 6px;
}

.summary-value {
    font-size: 1.2rem;
    font-weight: 700;
    color: var(--primary);
    word-break: break-word;
}

/* ===== DETAILS ===== */
.detail-group { 
    margin-bottom: 20px; 
}

.group-title {
    font-size: 0.9rem;
    font-weight: 700;
    color: var(--primary);
    margin-bottom: 8px;
    word-break: break-word;
}

.detail-row {
    display: flex;
    justify-content: space-between;
    align-items: center;
    gap: 12px;
    padding: 10px 0;
    border-bottom: 1px solid var(--border-color);
    font-size: 0.95rem;
    min-width: 0;
}

.detail-row:last-child { 
    border-bottom: none; 
}

.detail-label { 
    color: var(--text-secondary); 
    font-weight: 500; 
    flex: 0 0 40%;
    min-width: 0;
}

.detail-value { 
    color: var(--text-primary); 
    font-weight: 600; 
    text-align: right;
    flex: 1;
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.detail-value.verified { color: var(--success); }
.detail-value.unverified { color: var(--warning); }

/* ===== ADDRESS ===== */
.address-section { 
    margin-bottom: 16px; 
}

.address-box {
    background: var(--bg-primary);
    padding: 16px;
    border-radius: var(--radius-md);
    border-left: 4px solid var(--primary-light);
    margin-bottom: 12px;
    min-width: 0;
}

.address-label {
    font-size: 1rem;
    text-transform: uppercase;
    font-weight: 700;
    color: var(--primary);
    letter-spacing: 0.5px;
    margin-bottom: 8px;
    word-break: break-word;
}

.address-text {
    font-size: 0.9rem;
    color: var(--text-primary);
    line-height: 1.6;
    font-weight: 500;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.address-verify {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    margin-top: 8px;
    font-size: 0.8rem;
    color: var(--success);
    font-weight: 600;
}

.address-verify::before {
    content: "✓";
    display: inline-flex;
    align-items: center;
    justify-content: center;
    width: 16px;
    height: 16px;
    background: var(--success);
    color: white;
    border-radius: 50%;
    font-size: 10px;
}

/* ===== TABLE ===== */
.table-responsive {
    width: 100%;
    /* overflow-x: scroll;   force scroll always */
    -webkit-overflow-scrolling: touch;
    border-radius: var(--radius-md);
}
.table-responsive {
    overflow-x: auto;
}

.item-table {
    table-layout: fixed;
    width: 100%;
    min-width: 680px;
}

.item-table th,
.item-table td {
    vertical-align: middle;
}

.item-table th.col-item,
.item-table td.col-item {
    text-align: left;
}

.item-table th.col-center,
.item-table td.col-center {
    text-align: center;
}

.item-table th.col-right,
.item-table td.col-right {
    text-align: right;
}

.item-table .product-name {
    display: block;
    font-weight: 600;
    color: var(--text-primary);
    line-height: 1.35;
    margin-bottom: 2px;
}

.item-table .product-description {
    display: block;
    font-size: 0.8rem;
    color: var(--text-secondary);
    line-height: 1.35;
}

.item-table th {
    white-space: nowrap;
}

.item-table td {
    word-wrap: break-word;
}

/* ===== PRODUCTS TABLE ===== */
.products-table {
    width: 100%;
    border-collapse: collapse;
    margin-bottom: 16px;
}

.products-table thead { 
    background: var(--bg-primary); 
    border-bottom: 2px solid var(--border-color); 
}

.products-table th {
    padding: 12px;
    text-align: left;
    font-size: 0.8rem;
    font-weight: 700;
    text-transform: uppercase;
    color: var(--text-tertiary);
    letter-spacing: 0.5px;
}

.products-table td {
    padding: 12px;
    border-bottom: 1px solid var(--border-color);
    font-size: 0.9rem;
}

.products-table tbody tr:hover { 
    background: var(--bg-tertiary); 
}

.product-name { 
    font-weight: 600; 
    color: var(--text-primary); 
    overflow-wrap: anywhere;
    word-break: break-word;
}

.product-description { 
    font-size: 0.8rem; 
    color: var(--text-secondary); 
    margin-top: 2px; 
    overflow-wrap: anywhere;
    word-break: break-word;
}

.amount { 
    font-weight: 600; 
    color: var(--primary-light); 
}

/* ===== TOTALS ===== */
.totals-box { 
    background: var(--bg-tertiary); 
    padding: 16px; 
    border-radius: var(--radius-md); 
    margin-top: 16px; 
    border: 1px solid var(--border-color); 
}

.total-row { 
    display:flex; 
    justify-content:space-between; 
    gap: 12px;
    padding:8px 0; 
    font-size:0.95rem; 
    border-bottom:1px solid var(--border-color); 
}

.total-row:last-child { 
    border-bottom:none; 
}

.total-row.final { 
    border-top:2px solid var(--border-color); 
    padding-top:12px; 
    margin-top:12px; 
    font-size:1.1rem; 
    font-weight:700; 
}

.total-label { 
    color: var(--text-secondary); 
    min-width: 0;
}

.total-value { 
    font-weight:600; 
    color: var(--text-primary); 
    text-align: right;
    min-width: 0;
    overflow-wrap: anywhere;
    word-break: break-word;
}

.total-row.final .total-value { 
    color: var(--success); 
    font-size:1.2rem; 
}

/* ===== SECURITY SIGNALS ===== */
.security-signals { background: linear-gradient(135deg, rgba(30,64,175,0.08) 0%, rgba(59,130,246,0.05) 100%); border:1px solid rgba(59,130,246,0.2); border-radius: var(--radius-lg); padding:20px; margin-bottom:24px; }
.security-info { font-size:0.8rem; color: var(--text-secondary); margin-bottom:16px; line-height:1.5; padding:12px; background:white; border-radius:var(--radius-md); border-left:3px solid var(--primary-light); }
.signals-grid { display:grid; grid-template-columns:repeat(2,1fr); gap:12px; margin-bottom:16px; }
.signal-item { background:white; padding:12px; border-radius:var(--radius-md); border:1px solid var(--border-color); }
.signal-label { font-size:0.75rem; text-transform:uppercase; font-weight:700; color:var(--text-tertiary); letter-spacing:0.3px; margin-bottom:6px; }
.signal-value { font-size:0.9rem; font-weight:600; color:var(--text-primary); word-break: break-all; font-family:'Courier New', monospace; }
.signal-match { font-size:0.75rem; margin-top:6px; padding:4px 8px; background:rgba(34,197,94,0.1); border-radius:4px; color:var(--success); font-weight:600; }
.signal-match.mismatch { background:rgba(220,38,38,0.1); color:var(--danger); }
.risk-assessment { background:white; padding:12px; border-radius:var(--radius-md); border-left:4px solid var(--success); }
.risk-assessment.medium { border-left-color:var(--warning); }
.risk-assessment.high { border-left-color:var(--danger); }
.risk-label { font-size:0.75rem; text-transform:uppercase; font-weight:700; color:var(--text-tertiary); letter-spacing:0.3px; margin-bottom:6px; }
.risk-value { font-size:1rem; font-weight:700; color:var(--success); }
.risk-value.medium { color: var(--warning); }
.risk-value.high { color: var(--danger); }

/* ===== HIDE FRAUD / SECURITY SECTION ===== */
.security-signals,
.fraud-section,
#fraudSection,
#risk-assessment-box,
.signals-grid,
.security-info {
    display: none !important;
}

/* ===== OTP SECTION ===== */
.otp-container { 
    display:grid; 
    grid-template-columns:1fr 1fr; 
    gap:24px; 
    align-items: stretch;
}

.otp-section { 
    background: linear-gradient(135deg, #fef3c7 0%, #fef08a 100%); 
    border:2px dashed var(--warning); 
    border-radius:var(--radius-lg); 
    padding:20px; 
    min-width: 0;
}

.otp-section-title { 
    font-size:0.95rem; 
    font-weight:700; 
    color:var(--text-primary); 
    text-transform:uppercase; 
    letter-spacing:0.5px; 
    margin-bottom:12px; 
    display:flex; 
    align-items:center; 
    gap:8px; 
    line-height: 1.4;
    word-break: break-word;
}

.otp-description { 
    font-size:0.85rem; 
    color:var(--text-secondary); 
    line-height:1.6; 
    margin-bottom:12px; 
    word-break: break-word;
}

.otp-code-display { 
    background:white; 
    padding:16px; 
    border-radius:var(--radius-md); 
    text-align:center; 
    margin-bottom:12px; 
    border:2px solid var(--border-color); 
    font-family:'Courier New', monospace; 
    font-size:1.6rem; 
    font-weight:700; 
    color:var(--warning); 
    letter-spacing:12px; 
    min-height:64px; 
    display:flex; 
    align-items:center; 
    justify-content:center; 
    transition: var(--transition); 
    overflow: hidden;
}

.otp-code-display.error { border-color: var(--danger); color: var(--danger); background: rgba(220,38,38,0.05); }
.otp-code-display.success { border-color: var(--success); color: var(--success); background: rgba(5,150,105,0.05); }

.otp-info { 
    font-size:0.8rem; 
    color: var(--text-secondary); 
    margin-bottom:12px; 
    line-height:1.5; 
    background:white; 
    padding:10px; 
    border-radius:var(--radius-sm); 
}

.timer { 
    font-size:0.9rem; 
    font-weight:600; 
    margin-bottom:12px; 
    text-align:center; 
    color:var(--warning); 
}

.timer.expired { color: var(--danger); }

.btn-generate { 
    width:100%; 
    padding:12px; 
    background:linear-gradient(135deg, var(--warning), #f59e0b); 
    color:white; 
    border:none; 
    border-radius:var(--radius-md); 
    font-size:0.95rem; 
    font-weight:600; 
    cursor:pointer; 
    transition:var(--transition); 
    text-transform:uppercase; 
    letter-spacing:0.5px; 
    box-shadow:0 4px 12px rgba(217,119,6,0.2); 
}

.btn-generate:hover:not(:disabled) { transform:translateY(-2px); box-shadow:0 6px 16px rgba(217,119,6,0.3); }
.btn-generate:disabled { opacity:0.6; cursor:not-allowed; }

.otp-inputs { 
    display:flex; 
    gap:8px; 
    margin-bottom:12px; 
    justify-content:center; 
    flex-wrap: nowrap;
}

.otp-input { 
    width:45px; 
    height:50px; 
    border:2px solid var(--border-color); 
    border-radius:var(--radius-sm); 
    text-align:center; 
    font-size:1.3rem; 
    font-weight:700; 
    font-family:'Courier New', monospace; 
    transition:var(--transition); 
    background:white; 
    color:var(--text-primary); 
    min-width: 0;
}

.otp-input:focus { outline:none; border-color: var(--primary-light); box-shadow: 0 0 0 3px rgba(59,130,246,0.1); }
.otp-input.error { border-color:var(--danger); animation: shake 0.4s; }
.otp-input.success { border-color:var(--success); background: rgba(5,150,105,0.05); }

/* ===== VERIFICATION STATUS ===== */
.verification-status { background: var(--bg-primary); padding:16px; border-radius:var(--radius-md); text-align:center; margin-bottom:12px; border-left:4px solid var(--border-color); display:none; }
.verification-status.pending { border-left-color: var(--warning); background: rgba(217,119,6,0.05); }
.verification-status.verified { border-left-color: var(--success); background: rgba(5,150,105,0.05); display:block; }
.verification-status.error { border-left-color: var(--danger); background: rgba(220,38,38,0.05); display:block; }
.status-icon { font-size:1.8rem; margin-bottom:6px; display:block; }
.status-text { font-weight:600; font-size:0.9rem; color:var(--text-primary); word-break: break-word; }

/* ===== SUCCESS MODAL ===== */
.success-modal {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    background: rgba(15, 23, 42, 0.55);
    backdrop-filter: blur(6px);
    -webkit-backdrop-filter: blur(6px);
    display: flex;
    align-items: center;
    justify-content: center;
    z-index: 9999;
    padding: 20px;
}

.success-content {
    background: linear-gradient(180deg, #ffffff 0%, #f8fafc 100%);
    border-radius: 24px;
    padding: 34px 30px 28px;
    text-align: center;
    width: 100%;
    max-width: 420px;
    box-shadow: 0 24px 60px rgba(15, 23, 42, 0.22);
    animation: fadeInUp 0.35s ease-in-out;
    position: relative;
    border: 1px solid rgba(226, 232, 240, 0.95);
    overflow: hidden;
}

.success-content::before {
    content: "";
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    width: 100%;
    height: 6px;
    background: linear-gradient(135deg, var(--success), var(--primary-light));
}

.success-checkmark {
    width: 88px;
    height: 88px;
    margin: 0 auto 18px;
    border-radius: 50%;
    background: linear-gradient(135deg, rgba(5,150,105,0.16), rgba(34,197,94,0.10));
    display: flex;
    align-items: center;
    justify-content: center;
    color: var(--success);
    font-size: 42px;
    box-shadow: inset 0 0 0 6px rgba(5,150,105,0.08);
    animation: scaleAndShrink 0.4s ease-in-out;
}

.checkmark-circle {
    display: flex;
    align-items: center;
    justify-content: center;
    width: 58px;
    height: 58px;
    border-radius: 50%;
    background: linear-gradient(135deg, var(--success), #10b981);
    color: white;
    font-size: 28px;
    font-weight: 800;
    box-shadow: 0 10px 20px rgba(5,150,105,0.25);
}

.success-title {
    font-size: 1.5rem;
    font-weight: 800;
    color: var(--primary);
    margin-bottom: 10px;
    letter-spacing: -0.3px;
    word-break: break-word;
}

.success-message {
    font-size: 0.96rem;
    color: var(--text-secondary);
    margin-bottom: 24px;
    line-height: 1.7;
    font-weight: 500;
    word-break: break-word;
}

.success-button,
.success-btn {
    display: inline-flex;
    align-items: center;
    justify-content: center;
    min-width: 170px;
    padding: 13px 24px;
    background: linear-gradient(135deg, var(--primary), var(--primary-light));
    color: #fff;
    border: none;
    border-radius: 14px;
    font-weight: 700;
    font-size: 0.95rem;
    letter-spacing: 0.4px;
    cursor: pointer;
    transition: var(--transition);
    box-shadow: 0 10px 24px rgba(30, 64, 175, 0.25);
    max-width: 100%;
}

.success-button:hover,
.success-btn:hover {
    transform: translateY(-2px);
    box-shadow: 0 14px 28px rgba(30, 64, 175, 0.30);
}

.success-button:active,
.success-btn:active {
    transform: translateY(0);
}

/* ===== BUTTONS ===== */
.btn-primary { background: linear-gradient(135deg, var(--primary), var(--primary-light)); color:white; padding:12px 20px; border:none; border-radius:var(--radius-md); cursor:pointer; font-weight:600; transition:var(--transition); }
.btn-primary:hover { transform:translateY(-2px); box-shadow:0 4px 12px rgba(59,130,246,0.3); }
.btn-secondary { background:white; border:2px solid var(--primary-light); color:var(--primary); padding:12px 20px; border-radius:var(--radius-md); cursor:pointer; font-weight:600; transition:var(--transition); }
.btn-secondary:hover { background:var(--primary-light); color:white; }

/* ===== ALERTS ===== */
.alert-success { background: rgba(5,150,105,0.1); border-left:4px solid var(--success); padding:12px; border-radius:var(--radius-sm); color:var(--success); font-weight:600; margin-bottom:12px; }
.alert-error { background: rgba(220,38,38,0.1); border-left:4px solid var(--danger); padding:12px; border-radius:var(--radius-sm); color:var(--danger); font-weight:600; margin-bottom:12px; }
.alert-warning { background: rgba(245,158,11,0.1); border-left:4px solid var(--warning); padding:12px; border-radius:var(--radius-sm); color:var(--warning); font-weight:600; margin-bottom:12px; }

/* ===== ACTION BUTTON AREA ===== */
.action-buttons {
    display: flex;
    justify-content: center;
    align-items: center;
    margin-top: 28px;
    padding-top: 10px;
    width: 100%;
}

.action-buttons .btn,
.action-buttons .btn-primary {
    min-width: 220px;
    padding: 14px 28px;
    font-size: 1rem;
    font-weight: 700;
    border-radius: 14px;
    letter-spacing: 0.4px;
    box-shadow: 0 8px 20px rgba(30, 64, 175, 0.18);
    max-width: 100%;
}

/* ===== ANIMATIONS ===== */
@keyframes shake {
    0%,100% { transform:translateX(0); }
    25% { transform:translateX(-4px); }
    50% { transform:translateX(4px); }
    75% { transform:translateX(-4px); }
}
@keyframes fadeIn { from {opacity:0;} to {opacity:1;} }
@keyframes fadeInUp { from {opacity:0; transform:translateY(10px);} to {opacity:1; transform:translateY(0);} }
@keyframes scaleAndShrink { 0% { transform: scale(0.3); } 50% { transform: scale(1.2); } 100% { transform: scale(1); } }
@keyframes sparkleFloat { 0% { transform:translateY(0); opacity:1; } 100% { transform:translateY(-30px); opacity:0; } }

/* ===== RESPONSIVE ===== */
