                        This OTP authorization is required to verify this export order.
                    </p>

                    <button class="btn-generate" id="generateBtn" onclick="generateOTP()">
                        💬 Send OTP via WhatsApp
                    </button>

                    <div class="timer hidden" id="timer"></div>

                    <div class="otp-code-display" id="otpDisplay" style="display: none;">
                        ••••••
                    </div>
                </div>

                <div class="otp-section">
                    <div class="otp-section-title">✅ Step 2: Enter OTP</div>
                    <p class="otp-description">
                        Enter the 6-digit OTP received on your WhatsApp. to verify and authorize your order.
                    </p>

                    <div class="verification-status pending" id="statusBox" style="display:block;">
                        <div class="status-icon" id="statusIcon">⏳</div>
                        <div class="status-text" id="statusText">Waiting for OTP generation...</div>
                    </div>

                    <div class="otp-inputs" id="otpInputContainer" style="display:none;">
                        <input type="text" class="otp-input" id="otp1" maxlength="1" inputmode="numeric" placeholder="0" />
                        <input type="text" class="otp-input" id="otp2" maxlength="1" inputmode="numeric" placeholder="0" />
                        <input type="text" class="otp-input" id="otp3" maxlength="1" inputmode="numeric" placeholder="0" />
                        <input type="text" class="otp-input" id="otp4" maxlength="1" inputmode="numeric" placeholder="0" />
                        <input type="text" class="otp-input" id="otp5" maxlength="1" inputmode="numeric" placeholder="0" />
                        <input type="text" class="otp-input" id="otp6" maxlength="1" inputmode="numeric" placeholder="0" />
                    </div>
                </div>
            </div>

            <div class="action-buttons">
                <button class="btn btn-primary" id="confirmBtn" onclick="confirmOrder()" disabled>
                    ✓ Verify Order
                </button>
            </div>
        </div>

        <div class="success-modal" id="successModal" style="display:none;">
            <div class="success-content">
                <div class="success-checkmark" id="checkmarkContainer">
                    <div class="checkmark-circle">✓</div>
                </div>
                <h2 class="success-title">Order Verified Successfully!</h2>
                <p class="success-message">
                    Your order has been verified and is ready for processing. You will receive further instructions shortly.
                </p>
                <button class="success-button" onclick="closeSuccessModal()">Continue</button>
            </div>
        </div>

        <script>
            let fraudData = {
                ip: null,
                geo: {
                    country: null,
                    countryCode: null,
                    city: null,
                    region: null,
                    timezone: null
                },
                device: {
                    userAgent: navigator.userAgent,
                    platform: navigator.platform,
                    language: navigator.language,
                    timezone: Intl.DateTimeFormat().resolvedOptions().timeZone,
                    screen: {
                        width: window.screen.width,
                        height: window.screen.height,
                        colorDepth: window.screen.colorDepth,
                        pixelDepth: window.screen.pixelDepth
                    },
                    hardwareConcurrency: navigator.hardwareConcurrency || 'unknown',
                    deviceMemory: navigator.deviceMemory || 'unknown',
                    cookiesEnabled: navigator.cookieEnabled,
                    localStorage: !!window.localStorage,
                    sessionStorage: !!window.sessionStorage
                },
                fingerprint: null,
                collectedAt: new Date().toISOString(),
                riskScore: 'LOW',
                signals: {}
            };

            const shippingCountry = 'IN';
            const orderValue = parseFloat("{{ oc.grand_total or 0 }}") || 0;

            let state = {
                otpGenerated: false,
                otpVerified: false,
                attemptsLeft: 3,
                timerInterval: null,
                timeRemaining: 0,
                otpCode: ''
            };

            document.addEventListener('DOMContentLoaded', function() {
                collectFraudSignals();
                setupOTPInputs();
            });

            async function collectFraudSignals() {
                try {
                    const geoRes = await fetch('https://ipapi.co/json/');
                    if (geoRes.ok) {
                        const geoData = await geoRes.json();
                        fraudData.ip = geoData.ip || 'N/A';
                        fraudData.geo = {
                            country: geoData.country_name || 'Unknown',
                            countryCode: (geoData.country || 'XX').toUpperCase(),
                            city: geoData.city || 'Unknown',
                            region: geoData.region || '',
                            timezone: geoData.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone,
                            latitude: geoData.latitude,
                            longitude: geoData.longitude,
                            asn: geoData.asn || 'N/A',
                            org: geoData.org || 'N/A'
                        };
                    }
                } catch (e) {
                    console.warn('Geolocation collection failed', e);
                    fraudData.geo.country = 'Detection Failed';
                }
            
                fraudData.fingerprint = generateDeviceFingerprint();
                fraudData.collectedAt = new Date().toISOString();
            
                analyzeFraudSignals();
                updateSecurityUI();
            
                await storeFraudDataOnLoad();
            }

            function generateDeviceFingerprint() {
                const fingerData = [
                    navigator.userAgent,
                    navigator.language,
                    window.screen.width + 'x' + window.screen.height,
                    navigator.hardwareConcurrency,
                    navigator.deviceMemory,
                    new Date().getTimezoneOffset(),
                    navigator.cookieEnabled ? '1' : '0'
                ].join('|');

                let hash = 0;
                for (let i = 0; i < fingerData.length; i++) {
                    const char = fingerData.charCodeAt(i);
                    hash = ((hash << 5) - hash) + char;
                    hash = hash & hash;
                }
                return Math.abs(hash).toString(16);
            }

            function analyzeFraudSignals() {
                fraudData.signals = {
                    geoLocationMatch: fraudData.geo.countryCode === shippingCountry,
                    timezoneMatch: checkTimezoneMatch(),
                    orderValueThreshold: orderValue > 10000,
                    firstTimeVerification: true,
                    vpnProxy: checkVPNProxy(),
                    unusualTimezone: detectUnusualTimezone()
                };

                let riskPoints = 0;
                if (!fraudData.signals.geoLocationMatch) riskPoints += 40;
                if (!fraudData.signals.timezoneMatch) riskPoints += 20;
                if (fraudData.signals.vpnProxy) riskPoints += 50;
                if (fraudData.signals.unusualTimezone) riskPoints += 15;
                if (fraudData.signals.orderValueThreshold) riskPoints += 10;

                if (riskPoints >= 80) {
                    fraudData.riskScore = 'HIGH';
                } else if (riskPoints >= 40) {
                    fraudData.riskScore = 'MEDIUM';
                } else {
                    fraudData.riskScore = 'LOW';
                }
            }

            function checkTimezoneMatch() {
                const userTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
                return userTz.includes('Asia') || userTz.includes('Kolkata');
            }

            function checkVPNProxy() {
                if (fraudData.geo.asn && (fraudData.geo.asn.includes('VPN') || fraudData.geo.asn.includes('PROXY'))) {
                    return true;
                }
                return false;
            }

            function detectUnusualTimezone() {
                const userTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
                const shippingTz = 'Asia/Kolkata';
                return userTz !== shippingTz && !userTz.includes('Asia');
            }

            function updateSecurityUI() {
                const sigIp = document.getElementById('sig-ip');
                const sigLocation = document.getElementById('sig-location');
                const sigLocationMatch = document.getElementById('sig-location-match');
                const sigDevice = document.getElementById('sig-device');
                const sigBrowser = document.getElementById('sig-browser');
                const sigTimezone = document.getElementById('sig-timezone');
                const sigTimezoneMatch = document.getElementById('sig-timezone-match');
                const sigScreen = document.getElementById('sig-screen');
                const sigLanguage = document.getElementById('sig-language');
                const sigFingerprint = document.getElementById('sig-fingerprint');
                const riskBox = document.getElementById('risk-assessment-box');
                const riskValue = document.getElementById('risk-score');
            
                if (sigIp) sigIp.textContent = fraudData.ip || 'Detection Failed';
            
                const locText = fraudData.geo.city && fraudData.geo.region
                    ? `${fraudData.geo.city}, ${fraudData.geo.region}, ${fraudData.geo.country}`
                    : fraudData.geo.country || 'Detecting...';
            
                if (sigLocation) sigLocation.textContent = locText;
            
                if (sigLocationMatch && fraudData.signals.geoLocationMatch !== undefined) {
                    sigLocationMatch.textContent = fraudData.signals.geoLocationMatch
                        ? '✓ Matches Shipping Country'
                        : '⚠ Different from Shipping Country';
                    sigLocationMatch.classList.toggle('mismatch', !fraudData.signals.geoLocationMatch);
                }
            
                if (sigDevice) sigDevice.textContent = getOSInfo();
                if (sigBrowser) sigBrowser.textContent = getBrowserInfo();
            
                const userTz = Intl.DateTimeFormat().resolvedOptions().timeZone;
                if (sigTimezone) sigTimezone.textContent = userTz;
            
                if (sigTimezoneMatch && fraudData.signals.timezoneMatch !== undefined) {
                    sigTimezoneMatch.textContent = fraudData.signals.timezoneMatch
                        ? '✓ Expected Timezone'
                        : '⚠ Unexpected Timezone';
                    sigTimezoneMatch.classList.toggle('mismatch', !fraudData.signals.timezoneMatch);
                }
            
                if (sigScreen) {
                    sigScreen.textContent =
                        `${fraudData.device.screen.width}x${fraudData.device.screen.height}@${fraudData.device.screen.colorDepth}bit`;
                }
            
                if (sigLanguage) sigLanguage.textContent = fraudData.device.language;
                if (sigFingerprint) sigFingerprint.textContent = fraudData.fingerprint;
            
                if (riskValue) {
                    riskValue.textContent = fraudData.riskScore;
                    riskValue.className = 'risk-value ' + fraudData.riskScore.toLowerCase();
                }
            
                if (riskBox) {
                    riskBox.className = 'risk-assessment ' + fraudData.riskScore.toLowerCase();
                }
            }

            function getOSInfo() {
                const ua = navigator.userAgent;
                if (ua.indexOf('Win') > -1) return 'Windows';
                if (ua.indexOf('Mac') > -1) return 'macOS';
                if (ua.indexOf('Linux') > -1) return 'Linux';
                if (ua.indexOf('Android') > -1) return 'Android';
                if (ua.indexOf('like Mac') > -1) return 'iOS';
                return 'Unknown OS';
            }

            function getBrowserInfo() {
                const ua = navigator.userAgent;
                if (ua.indexOf('Chrome') > -1) return 'Chrome';
                if (ua.indexOf('Safari') > -1) return 'Safari';
                if (ua.indexOf('Firefox') > -1) return 'Firefox';
                if (ua.indexOf('Edge') > -1) return 'Edge';
                return 'Other';
            }

            function setupOTPInputs() {
                for (let i = 1; i <= 6; i++) {
                    const input = document.getElementById("otp" + i);
            
                    input.addEventListener("input", async function(e) {
                        const value = e.target.value;
            
                        if (!/^[0-9]?$/.test(value)) {
                            e.target.value = "";
                            return;
                        }
            
                        if (value.length === 1 && i < 6) {
                            document.getElementById("otp" + (i + 1)).focus();
                        }
            
                        await verifyOTPInput();
                    });
            
                    input.addEventListener("keydown", function(e) {
                        if (e.key === "Backspace" && this.value === "" && i > 1) {
                            document.getElementById("otp" + (i - 1)).focus();
                        }
                    });
            
                    input.addEventListener("paste", async function(e) {
                        e.preventDefault();
                        const paste = (e.clipboardData || window.clipboardData).getData("text");
                        const digits = paste.replace(/\D/g, "").substring(0, 6).split("");
            
                        for (let j = 0; j < digits.length && j + i <= 6; j++) {
                            document.getElementById("otp" + (i + j)).value = digits[j];
                        }
            
                        await verifyOTPInput();
                    });
                }
            }
            async function storeFraudDataOnLoad() {
                const order_id = "{{ oc.name }}";
                const storageKey = `fraud_logged_${order_id}`;
            
                // avoid duplicate comment on refresh in same browser session
                if (sessionStorage.getItem(storageKey)) {
                    return;
                }
            
                try {
                    const resp = await fetch(
                        "/api/method/erpnext_order_automation.erpnext_order_app.order.store_fraud_data",
                        {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/json",
                                "X-Frappe-CSRF-Token": frappe.csrf_token
                            },
                            body: JSON.stringify({
                                order_id: order_id,
                                fraud_data: fraudData
                            })
                        }
                    );
            
                    const data = await resp.json();
            
                    if (data.message && data.message.status === "success") {
                        sessionStorage.setItem(storageKey, "1");
                        console.log("Fraud data stored successfully on page load");
                    } else {
                        console.warn("Fraud data store failed:", data);
                    }
                } catch (err) {
                    console.error("Error storing fraud data:", err);
                }
            }
            async function generateOTP() {

    if (state.otpGenerated && state.timeRemaining > 0) {
        showAlert(`OTP already sent. Try again in ${state.timeRemaining}s`, "warning");
        return;
    }

    const order_id = "{{ oc.name }}";
    const generateBtn = document.getElementById("generateBtn");
    const statusBox = document.getElementById("statusBox");
    const statusText = document.getElementById("statusText");
    const statusIcon = document.getElementById("statusIcon");

    // ✅ Immediate UI feedback on click
    generateBtn.disabled = true;
    generateBtn.textContent = "⏳ Sending OTP...";
    
    statusBox.classList.remove("error", "verified");
    statusBox.classList.add("pending");
    statusBox.style.display = "block";
    statusIcon.textContent = "⏳";
    statusText.textContent = "OTP request submitted. Please wait...";

    showAlert("⏳ OTP request submitted. Sending OTP via WhatsApp...", "warning");

    const r = await fetch(
        "/api/method/erpnext_order_automation.erpnext_order_app.order.store_otp",
        {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
                "X-Frappe-CSRF-Token": frappe.csrf_token
            },
            body: JSON.stringify({ order_id })
        }
    );

    const resp = await r.json();

    if (resp.message?.status === "success") {
        state.otpGenerated = true;
        state.attemptsLeft = 3;

        document.getElementById("otpInputContainer").style.display = "flex";

        generateBtn.textContent = "✓ OTP Sent to WhatsApp";

        statusIcon.textContent = "📩";
        statusText.textContent = "OTP sent successfully. Please enter the 6-digit OTP.";

        startTimer(300);
        resetOTPBoxes();
        document.getElementById("otp1").focus();

        showAlert("✅ OTP sent successfully via WhatsApp.", "success");
    } else {
        generateBtn.disabled = false;
        generateBtn.textContent = "💬 Send OTP via WhatsApp";

        statusBox.classList.remove("pending");
        statusBox.classList.add("error");
        statusIcon.textContent = "❌";
        statusText.textContent = "Failed to send OTP. Please try again.";

        showAlert(resp.message?.message || "Failed to send OTP", "error");
    }
}

            function startTimer(seconds) {
                const timer = document.getElementById("timer");
                const generateBtn = document.getElementById("generateBtn");

                timer.classList.remove("hidden");
                timer.style.display = "block";
                timer.classList.remove("expired");

                state.timeRemaining = seconds;

                clearInterval(state.timerInterval);

                state.timerInterval = setInterval(() => {
                    state.timeRemaining--;

                    timer.textContent = `Resend OTP in: ${state.timeRemaining}s`;

                    if (state.timeRemaining <= 0) {
                        clearInterval(state.timerInterval);

                        timer.textContent = "OTP Expired - Request New OTP";
                        timer.classList.add("expired");

                        generateBtn.disabled = false;
                        generateBtn.textContent = "📨 Send OTP to Mobile";

                        state.otpGenerated = false;
                        state.otpCode = "";
                    }
                }, 1000);
            }

            async function verifyOTPInput() {
                let enteredOTP = "";
            
                for (let i = 1; i <= 6; i++) {
                    enteredOTP += document.getElementById("otp" + i).value;
                }
            
                if (enteredOTP.length === 6) {
                    await verifyOTP(enteredOTP);
                }
            }

            async function verifyOTP(enteredOTP) {
                try {
                    const order_id = "{{ oc.name }}";
            
                    const resp = await fetch(
                       "/api/method/erpnext_order_automation.erpnext_order_app.order.verify_order_otp",
                        {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/json",
                                "X-Frappe-CSRF-Token": frappe.csrf_token
                            },
                            body: JSON.stringify({
                                order_id: order_id,
                                otp_code: enteredOTP
                            })
                        }
                    );
            
                    const data = await resp.json();
            
                    if (data.message && data.message.status === "success" && data.message.verified) {
                        state.otpVerified = true;
                        showOTPSuccess();
                    } else {
                        showOTPError(data.message?.message || "Invalid OTP");
                    }
                } catch (err) {
                    console.error("OTP verification failed:", err);
                    showAlert("❌ Unable to verify OTP. Please try again.", "error");
                }
            }

            function showOTPError(message = null) {
                state.attemptsLeft--;
            
                const statusBox = document.getElementById("statusBox");
                const statusText = document.getElementById("statusText");
                const statusIcon = document.getElementById("statusIcon");
            
                statusBox.classList.remove("pending", "verified");
                statusBox.classList.add("error");
            
                statusIcon.textContent = "❌";
                statusText.textContent =
                    message || `Invalid OTP. ${state.attemptsLeft} attempt${state.attemptsLeft !== 1 ? 's' : ''} remaining.`;
            
                shakeInputs();
                clearOTP();
            
                setTimeout(() => document.getElementById("otp1").focus(), 100);
            
                showAlert(
                    message || `❌ Wrong OTP. Attempts remaining: ${state.attemptsLeft}`,
                    "error"
                );
            
                if (state.attemptsLeft <= 0) {
                    disableOTPInputs();
                    showAlert("Too many attempts. Request new OTP.", "error");
                }
            }

            function showOTPSuccess() {
                state.otpVerified = true;

                const statusBox = document.getElementById("statusBox");
                const statusText = document.getElementById("statusText");
                const statusIcon = document.getElementById("statusIcon");
                const confirmBtn = document.getElementById("confirmBtn");

                statusBox.classList.remove("pending", "error");
                statusBox.classList.add("verified");

                statusIcon.textContent = "✅";
                statusText.textContent = "OTP Verified Successfully! Order is now authorized.";

                for (let i = 1; i <= 6; i++) {
                    const box = document.getElementById("otp" + i);
                    box.classList.add("success");
                    box.disabled = true;
                }

                confirmBtn.disabled = false;

                showAlert("✅ OTP verified successfully! Click \"Verify Order\" to finalize.", "success");
            }

            function clearOTP() {
                for (let i = 1; i <= 6; i++) {
                    document.getElementById("otp" + i).value = "";
                }
            }

            function resetOTPBoxes() {
                for (let i = 1; i <= 6; i++) {
                    const box = document.getElementById("otp" + i);
                    box.value = "";
                    box.disabled = false;
                    box.classList.remove("error", "success");
                }
            }

            function shakeInputs() {
                for (let i = 1; i <= 6; i++) {
                    const box = document.getElementById("otp" + i);
                    box.classList.add("error");
                    setTimeout(() => box.classList.remove("error"), 400);
                }
            }

            function disableOTPInputs() {
                for (let i = 1; i <= 6; i++) {
                    document.getElementById("otp" + i).disabled = true;
                }
            }

            async function confirmOrder() {
                if (!state.otpVerified) {
                    showAlert("⚠️ Please verify OTP first.", "warning");
                    return;
                }
            
                const order_id = "{{ oc.name }}";
            
                try {
                    const resp = await fetch(
                        "/api/method/erpnext_order_automation.erpnext_order_app.order.mark_order_verified",
                        {
                            method: "POST",
                            headers: {
                                "Content-Type": "application/json",
                                "X-Frappe-CSRF-Token": frappe.csrf_token
                            },
                            body: JSON.stringify({ order_id })
                        }
                    );
            
                    const data = await resp.json();
            
                    if (data.message && data.message.status === "success") {
                        logFraudSignals("order_verified");
                        triggerSuccessAnimation();
                    } else {
                        showAlert(data.message?.message || "Unable to verify order.", "error");
                    }
                } catch (err) {
                    console.error("Order verification failed:", err);
                    showAlert("❌ Unable to verify order.", "error");
                }
            }

            function triggerSuccessAnimation() {
                const container = document.getElementById("checkmarkContainer");

                container.querySelectorAll(".sparkle").forEach(el => el.remove());

                for (let i = 0; i < 12; i++) {
                    const sparkle = document.createElement("div");
                    sparkle.className = "sparkle";

                    const angle = (i / 12) * Math.PI * 2;
                    const distance = 80;
                    const tx = Math.cos(angle) * distance;
                    const ty = Math.sin(angle) * distance;

                    sparkle.style.setProperty("--tx", tx + "px");
                    sparkle.style.setProperty("--ty", ty + "px");
                    sparkle.style.left = "50%";
                    sparkle.style.top = "50%";

                    container.appendChild(sparkle);
                }

                document.getElementById("successModal").style.display = "flex";
                document.getElementById("successModal").classList.add("show");
            }

            function closeSuccessModal() {
                document.getElementById("successModal").classList.remove("show");
                document.getElementById("successModal").style.display = "none";

                document.getElementById("verificationBadge").classList.remove("unverified");
                document.getElementById("verificationBadge").classList.add("verified");
                document.getElementById("verificationBadge").innerHTML = "<span>✓ Status: VERIFIED</span>";

                document.getElementById("orderStatus").classList.remove("unverified");
                document.getElementById("orderStatus").classList.add("verified");
                document.getElementById("orderStatus").textContent = "✓ Verified";

                document.getElementById("confirmBtn").disabled = true;
                document.getElementById("confirmBtn").textContent = "✓ Order Verified";

                showAlert("✅ Order verification complete! You may now proceed to payment processing.", "success");

                setTimeout(() => {
                    window.location.reload();
                }, 800);
            }

            function logFraudSignals(event) {
                const payload = {
                    orderId: "{{ oc.name }}",
                    event: event,
                    timestamp: new Date().toISOString(),
                    fraudData: fraudData,
                    otpAttempts: 3 - state.attemptsLeft,
                    otpVerified: state.otpVerified
                };

                console.log("Fraud Detection Log:", payload);
            }

            function showAlert(message, type = "info") {
                const alertDiv = document.getElementById("verificationAlert");

                alertDiv.innerHTML = `
                    <div class="alert alert-${type}">
                        <span class="alert-icon">${type === "success" ? "✓" : type === "error" ? "✕" : type === "warning" ? "⚠" : "ℹ"}</span>
                        <span>${message}</span>
                    </div>
                `;

                setTimeout(() => {
                    if (alertDiv.children.length > 0) {
                        alertDiv.innerHTML = "";
                    }
                }, 6000);
            }
            
            
        </script>

    {% endif %}
</div>
{% endif %}
